import{_ as r,o as a,c as o,a2 as s}from"./chunks/framework.BQq6mqvm.js";const p=JSON.parse('{"title":"分享文件与文件夹","description":"","frontmatter":{},"headers":[],"relativePath":"usage/share.md","filePath":"usage/share.md","lastUpdated":1790385461000}'),e={name:"usage/share.md"};function n(l,t,d,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="分享文件与文件夹" tabindex="-1">分享文件与文件夹 <a class="header-anchor" href="#分享文件与文件夹" aria-label="Permalink to &quot;分享文件与文件夹&quot;">​</a></h1><p>想把一个文件发给不在内网的同事、客户？用<strong>分享链接</strong>就行，对方不用登录、不用装任何东西， 在浏览器里打开链接就能下载。</p><h2 id="怎么分享" tabindex="-1">怎么分享 <a class="header-anchor" href="#怎么分享" aria-label="Permalink to &quot;怎么分享&quot;">​</a></h2><p>在<strong>我的文件</strong>里找到要分享的文件，点右边的<strong>分享</strong>按钮，然后选一个有效期：</p><table tabindex="0"><thead><tr><th>有效期</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>永久</strong>（默认）</td><td>长期给对方用的资料</td></tr><tr><td>1 天 / 3 天 / 7 天 / 30 天</td><td>临时给对方看一眼，到期自动失效</td></tr></tbody></table><p>点「创建链接」后，链接会<strong>自动复制到剪贴板</strong>，直接粘贴到聊天工具里发给对方即可。</p><div class="warning custom-block"><p class="custom-block-title">只能分享自己的文件</p><p>分享按钮只出现在你自己上传的文件上。别人上传的文件你能浏览、能下载， 但不能替他生成分享链接。</p></div><h2 id="文件夹也能分享" tabindex="-1">文件夹也能分享 <a class="header-anchor" href="#文件夹也能分享" aria-label="Permalink to &quot;文件夹也能分享&quot;">​</a></h2><p>进入某个文件夹后，文件夹卡片右侧也有<strong>分享</strong>按钮。对方打开链接可以看到这个文件夹里 有哪些文件，点一下就能把<strong>整个文件夹打包成 zip</strong> 下载走。</p><h2 id="对方看到什么" tabindex="-1">对方看到什么 <a class="header-anchor" href="#对方看到什么" aria-label="Permalink to &quot;对方看到什么&quot;">​</a></h2><p>打开链接的人不需要登录，会直接看到：</p><ul><li>文件名和大小，以及<strong>是谁分享的</strong>；</li><li>图片、PDF、音视频可以直接在页面上看；</li><li>其他类型（Word、Excel、压缩包等）点按钮下载；</li><li>有效期状态（比如「剩 3 天」或「永久有效」）。</li></ul><h2 id="链接为什么会打不开" tabindex="-1">链接为什么会打不开 <a class="header-anchor" href="#链接为什么会打不开" aria-label="Permalink to &quot;链接为什么会打不开&quot;">​</a></h2><p>失效时页面会<strong>明确告诉你原因</strong>，三种情况不是一回事：</p><table tabindex="0"><thead><tr><th>页面提示</th><th>意思</th><th>怎么办</th></tr></thead><tbody><tr><td><strong>该分享链接已过期</strong></td><td>有效期到了</td><td>找分享的人重新生成一个链接</td></tr><tr><td><strong>分享的文件已被删除</strong></td><td>内容已经不在服务器上了</td><td>找分享的人确认</td></tr><tr><td><strong>分享链接无效或已被撤销</strong></td><td>链接不完整，或者分享的人把链接撤销了</td><td>检查链接是否复制完整</td></tr></tbody></table><h2 id="改名字、挪位置都不影响链接" tabindex="-1">改名字、挪位置都不影响链接 <a class="header-anchor" href="#改名字、挪位置都不影响链接" aria-label="Permalink to &quot;改名字、挪位置都不影响链接&quot;">​</a></h2><p>分享链接指向的是<strong>这个文件本身</strong>，不是它当时所在的位置。所以：</p><ul><li>你把文件<strong>改个名字</strong>，对方的链接照样能打开，显示的是新名字；</li><li>你把文件<strong>移到别的文件夹</strong>，链接也照样能用。</li></ul><p>反过来，<strong>你把文件删掉</strong>（或删掉它所在的文件夹），对方的链接就会提示 「分享的文件已被删除」—— 这时文件在回收站里，管理员还能恢复； 一旦管理员恢复，<strong>同一个链接会自动重新生效</strong>，不用重新发给对方。</p><h2 id="管理自己发出的链接" tabindex="-1">管理自己发出的链接 <a class="header-anchor" href="#管理自己发出的链接" aria-label="Permalink to &quot;管理自己发出的链接&quot;">​</a></h2><p>左侧菜单的<strong>分享管理</strong>里能看到所有分享链接：</p><ul><li>默认显示<strong>所有人创建的</strong>分享（能看到是谁分享的、还剩多少天、被打开过几次）， 这样同一个文件不用重复问别人要链接；</li><li>点「只看我的」可以筛出自己创建的那些；</li><li>每个链接都能点<strong>复制</strong>重新拿回地址；</li><li>不需要了可以点<strong>撤销</strong>，撤销后链接<strong>立刻失效</strong>，已经发出去的也打不开了。</li></ul><div class="tip custom-block"><p class="custom-block-title">永久链接也会留在列表里</p><p>永久分享不会自己消失。定期到「分享管理」里清一清已经不用的链接，是个好习惯。</p></div>',23)])])}const u=r(e,[["render",n]]);export{p as __pageData,u as default};
